import{ar as n,as as a,at as e,au as p}from"./app-5nod3Nrs.js";const t={};function l(c,s){return p(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="四、其他相关" tabindex="-1"><a class="header-anchor" href="#四、其他相关"><span>四、其他相关</span></a></h1><h2 id="_4-1-渲染模式" tabindex="-1"><a class="header-anchor" href="#_4-1-渲染模式"><span>4.1 渲染模式</span></a></h2><h3 id="_4-1-1-渲染类型" tabindex="-1"><a class="header-anchor" href="#_4-1-1-渲染类型"><span>4.1.1 渲染类型</span></a></h3><p>SvelteKit 是一个全栈元框架，原生支持三种核心渲染模式：</p><ul><li>SSR（Server-Side Rendering）：服务端渲染，动态内容 + SEO 友好</li><li>SSG（Static Site Generation）：静态生成，构建时预渲染 HTML</li><li>CSR（Client-Side Rendering）：纯客户端渲染（默认后备行为）</li></ul><table><thead><tr><th>模式</th><th>何时渲染</th><th>适用场景</th><th>SEO</th><th>性能</th></tr></thead><tbody><tr><td>SSR</td><td>每次请求时（服务端）</td><td>动态内容（用户仪表盘、实时数据）</td><td>优秀</td><td>快（首屏）</td></tr><tr><td>SSG</td><td>构建时（一次生成）</td><td>静态内容（博客、文档、营销页）</td><td>优秀</td><td>极快（CDN）</td></tr><tr><td>CSR</td><td>浏览器加载后</td><td>内部工具、管理后台（无需 SEO）</td><td>差</td><td>首屏慢</td></tr></tbody></table><p>SvelteKit 默认采用 混合渲染：</p><ul><li>首屏：SSR（或 SSG）</li><li>后续导航：CSR（SPA 体验）</li></ul><h3 id="_4-1-2-全局配置-svelte-config-js" tabindex="-1"><a class="header-anchor" href="#_4-1-2-全局配置-svelte-config-js"><span>4.1.2 全局配置（<code>svelte.config.js</code>）</span></a></h3><p>通过 <strong>适配器（Adapter）</strong> 决定部署目标和默认渲染行为：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// svelte.config.js</span></span>
<span class="line"><span class="token keyword">import</span> adapter <span class="token keyword">from</span> <span class="token string">&#39;@sveltejs/adapter-auto&#39;</span><span class="token punctuation">;</span> <span class="token comment">// 自动选择适配器</span></span>
<span class="line"><span class="token comment">// 或指定：</span></span>
<span class="line"><span class="token comment">// import adapter from &#39;@sveltejs/adapter-node&#39;;    // SSR（Node 服务器）</span></span>
<span class="line"><span class="token comment">// import adapter from &#39;@sveltejs/adapter-static&#39;;  // SSG（静态站点）</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/** <span class="token keyword">@type</span> <span class="token class-name"><span class="token punctuation">{</span><span class="token keyword">import</span><span class="token punctuation">(</span><span class="token string">&#39;@sveltejs/kit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Config<span class="token punctuation">}</span></span> */</span></span>
<span class="line"><span class="token keyword">const</span> config <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">kit</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">adapter</span><span class="token operator">:</span> <span class="token function">adapter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token comment">// 全局 prerender 设置</span></span>
<span class="line">        <span class="token literal-property property">prerender</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token literal-property property">entries</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&#39;/&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;/about&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;/blog&#39;</span><span class="token punctuation">]</span> <span class="token comment">// 显式指定 SSG 路由</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">default</span> config<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>🔔 <strong>关键</strong>：</p><ul><li><code>adapter-static</code> → 强制 SSG（所有页面必须可静态生成）</li><li><code>adapter-node</code> / <code>adapter-cloudflare</code> 等 → 支持 SSR + SSG 混合</li></ul></blockquote><h3 id="_4-1-3-按路由配置渲染模式" tabindex="-1"><a class="header-anchor" href="#_4-1-3-按路由配置渲染模式"><span>4.1.3 按路由配置渲染模式</span></a></h3><p>SvelteKit 允许<strong>每个路由单独控制</strong>是否 SSR、SSG 或 CSR。</p><ol><li><p><strong>启用 SSG（静态生成）</strong></p><p>在 <code>+page.js</code> 或 <code>+layout.js</code> 中设置：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/routes/blog/+page.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> prerender <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token comment">//  构建时生成静态 HTML</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>要求：</p><ul><li><code>load</code> 函数不能依赖请求时信息（如 <code>cookies</code>, <code>request.headers</code>）</li><li>所有数据必须在构建时可获取</li></ul></blockquote></li><li><p><strong>禁用 SSR（强制 CSR）</strong></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/routes/dashboard/+page.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> ssr <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span> <span class="token comment">// ❌ 不在服务端渲染，仅客户端激活</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> csr <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>  <span class="token comment">// （默认 true，可省略）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>适用场景：</p><ul><li>内部管理面板（无需 SEO）</li><li>重度交互应用（如画板、游戏）</li></ul></blockquote></li><li><p><strong>混合模式（默认）</strong></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/routes/+page.js</span></span>
<span class="line"><span class="token comment">// 不设置 ssr/prerender → 默认行为：</span></span>
<span class="line"><span class="token comment">// - 首屏：SSR（服务端渲染 HTML）</span></span>
<span class="line"><span class="token comment">// - 客户端：水合（hydration）后变为 CSR</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><h3 id="_4-1-4-数据加载与渲染模式的关系" tabindex="-1"><a class="header-anchor" href="#_4-1-4-数据加载与渲染模式的关系"><span>4.1.4 数据加载与渲染模式的关系</span></a></h3><ol><li><p>SSR / SSG：使用 <code>+page.server.js</code></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/routes/profile/+page.server.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">load</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> locals<span class="token punctuation">,</span> params <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 可安全访问数据库、私有 API</span></span>
<span class="line">  <span class="token keyword">const</span> user <span class="token operator">=</span> <span class="token keyword">await</span> db<span class="token punctuation">.</span><span class="token function">getUser</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> user <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>CSR：只能使用 <code>+page.js</code>（无服务端上下文）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/routes/app/+page.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">load</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 仅能调用公开 API</span></span>
<span class="line">  <span class="token keyword">const</span> data <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;/api/public-data&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">r</span> <span class="token operator">=&gt;</span> r<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> data <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>如果设置 <code>ssr: false</code>，则 <strong><code>+page.server.js</code> 不会运行</strong>！</p></blockquote></li></ol><h2 id="_4-2-生命周期钩子" tabindex="-1"><a class="header-anchor" href="#_4-2-生命周期钩子"><span>4.2 生命周期钩子</span></a></h2><p>在 SvelteKit 中，<code>hooks.client.js</code> 和 <code>hooks.server.js</code> 是两个核心的<strong>生命周期钩子文件</strong>，用于在请求/导航的不同阶段插入自定义逻辑。它们分别运行在<strong>客户端</strong>和<strong>服务端</strong>，职责完全不同。</p><h3 id="_4-2-1-总体对比" tabindex="-1"><a class="header-anchor" href="#_4-2-1-总体对比"><span>4.2.1 总体对比</span></a></h3><table><thead><tr><th>特性</th><th><code>hooks.server.js</code></th><th><code>hooks.client.js</code></th></tr></thead><tbody><tr><td><strong>运行环境</strong></td><td>服务端（Node.js / Edge Runtime）</td><td>客户端（浏览器）</td></tr><tr><td><strong>触发时机</strong></td><td>每个 HTTP 请求（包括页面加载、API 调用、actions）</td><td>每次客户端导航（SPA 跳转）</td></tr><tr><td><strong>可访问内容</strong></td><td><code>request</code>, <code>cookies</code>, <code>env</code>, <code>platform</code>, <code>locals</code></td><td><code>navigation</code>, <code>route</code>, <code>url</code></td></tr><tr><td><strong>主要用途</strong></td><td>认证、日志、权限控制、数据预处理</td><td>页面切换动画、埋点、滚动恢复、错误上报</td></tr><tr><td><strong>是否影响 SEO</strong></td><td>是（参与 SSR）</td><td>否（仅客户端）</td></tr></tbody></table><blockquote><p><strong>一句话总结</strong>：</p><ul><li><strong><code>server hooks</code> = 后端中间件</strong></li><li><strong><code>client hooks</code> = 前端导航拦截器</strong></li></ul></blockquote><h3 id="_4-2-2-hooks-server-js-——-服务端钩子" tabindex="-1"><a class="header-anchor" href="#_4-2-2-hooks-server-js-——-服务端钩子"><span>4.2.2 <code>hooks.server.js</code> —— 服务端钩子</span></a></h3><ol><li><p>执行流程</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">请求进入 → handleFetch (可选) → handle (主逻辑) → 返回响应</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p>核心函数</p><ol><li><code>handle</code>（最常用）</li></ol><p>在<strong>每个服务端请求前</strong>执行（包括 <code>load</code>、<code>actions</code>、<code>+server.js</code>）。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/hooks.server.js</span></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">{</span> sequence <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;@sveltejs/kit/hooks&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/** <span class="token keyword">@type</span> <span class="token class-name"><span class="token punctuation">{</span><span class="token keyword">import</span><span class="token punctuation">(</span><span class="token string">&#39;@sveltejs/kit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Handle<span class="token punctuation">}</span></span> */</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">auth</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> event<span class="token punctuation">,</span> resolve <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> session <span class="token operator">=</span> event<span class="token punctuation">.</span>cookies<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&#39;session&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 将用户信息注入 locals（所有服务端函数可访问）</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>session<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    event<span class="token punctuation">.</span>locals<span class="token punctuation">.</span>user <span class="token operator">=</span> <span class="token keyword">await</span> db<span class="token punctuation">.</span><span class="token function">getUserBySession</span><span class="token punctuation">(</span>session<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    event<span class="token punctuation">.</span>locals<span class="token punctuation">.</span>user <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 继续处理请求</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">resolve</span><span class="token punctuation">(</span>event<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/** <span class="token keyword">@type</span> <span class="token class-name"><span class="token punctuation">{</span><span class="token keyword">import</span><span class="token punctuation">(</span><span class="token string">&#39;@sveltejs/kit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>Handle<span class="token punctuation">}</span></span> */</span></span>
<span class="line"><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">logger</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> event<span class="token punctuation">,</span> resolve <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> start <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">resolve</span><span class="token punctuation">(</span>event<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> duration <span class="token operator">=</span> Date<span class="token punctuation">.</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> start<span class="token punctuation">;</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>event<span class="token punctuation">.</span>request<span class="token punctuation">.</span>method<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>event<span class="token punctuation">.</span>url<span class="token punctuation">.</span>pathname<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> - </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>duration<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">ms</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> response<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 使用 sequence 组合多个钩子（按顺序执行）</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> handle <span class="token operator">=</span> <span class="token function">sequence</span><span class="token punctuation">(</span>auth<span class="token punctuation">,</span> logger<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>典型用例</strong>：</p><ul><li>用户认证（设置 <code>locals.user</code>）</li><li>权限检查（如 <code>/admin</code> 路由拦截）</li><li>请求日志</li><li>多语言 i18n 初始化</li><li>API 代理（修改 <code>fetch</code> 行为）</li></ul></blockquote><ol start="2"><li><code>handleFetch</code>（高级用法）</li></ol><p>拦截组件中 <code>load()</code> 函数使用的 <code>fetch</code> 调用。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/hooks.server.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">handleFetch</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> request<span class="token punctuation">,</span> fetch <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 例如：为内部 API 自动添加认证头</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>request<span class="token punctuation">.</span>url<span class="token punctuation">.</span><span class="token function">startsWith</span><span class="token punctuation">(</span><span class="token string">&#39;https://api.myapp.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    request<span class="token punctuation">.</span>headers<span class="token punctuation">.</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string">&#39;Authorization&#39;</span><span class="token punctuation">,</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Bearer </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>process<span class="token punctuation">.</span>env<span class="token punctuation">.</span><span class="token constant">INTERNAL_TOKEN</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">fetch</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：仅影响 <strong>服务端 <code>load</code> 中的 <code>fetch</code></strong>，不影响客户端 <code>fetch</code>。</p></blockquote></li></ol><h3 id="_4-2-3-hooks-client-js-——-客户端钩子" tabindex="-1"><a class="header-anchor" href="#_4-2-3-hooks-client-js-——-客户端钩子"><span>4.2.3 <code>hooks.client.js</code> —— 客户端钩子</span></a></h3><ol><li><p>执行流程</p><div class="language-txt line-numbers-mode" data-highlighter="prismjs" data-ext="txt"><pre><code class="language-txt"><span class="line">用户点击链接/调用 goto() → handleError (可选) → handle (主逻辑) → 页面切换</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></li><li><p>核心函数</p><ol><li><code>handle</code>（最常用）</li></ol><p>在<strong>每次客户端导航前</strong>执行（仅 SPA 跳转，不包括首次页面加载）。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/hooks.client.js</span></span>
<span class="line"><span class="token doc-comment comment">/** <span class="token keyword">@type</span> <span class="token class-name"><span class="token punctuation">{</span><span class="token keyword">import</span><span class="token punctuation">(</span><span class="token string">&#39;@sveltejs/kit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>HandleClient<span class="token punctuation">}</span></span> */</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">handle</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> event<span class="token punctuation">,</span> resolve <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 例如：页面切换时显示加载条</span></span>
<span class="line">  document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;#loading-bar&#39;</span><span class="token punctuation">)</span><span class="token operator">?.</span>classList<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token string">&#39;active&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">resolve</span><span class="token punctuation">(</span>event<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 导航完成后隐藏加载条</span></span>
<span class="line">  document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;#loading-bar&#39;</span><span class="token punctuation">)</span><span class="token operator">?.</span>classList<span class="token punctuation">.</span><span class="token function">remove</span><span class="token punctuation">(</span><span class="token string">&#39;active&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">return</span> response<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>典型用例</strong>：</p><ul><li>全局加载指示器</li><li>页面切换动画</li><li>埋点统计（记录用户行为）</li><li>滚动位置保存/恢复</li><li>在线状态检测</li></ul></blockquote><ol start="2"><li><code>handleError</code>（错误处理）</li></ol><p>捕获<strong>客户端运行时错误</strong>（如组件渲染错误、<code>load</code> 抛出异常）。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/hooks.client.js</span></span>
<span class="line"><span class="token doc-comment comment">/** <span class="token keyword">@type</span> <span class="token class-name"><span class="token punctuation">{</span><span class="token keyword">import</span><span class="token punctuation">(</span><span class="token string">&#39;@sveltejs/kit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>HandleClientError<span class="token punctuation">}</span></span> */</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">handleError</span><span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> error<span class="token punctuation">,</span> event <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 上报错误到 Sentry 等监控服务</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&#39;Client error:&#39;</span><span class="token punctuation">,</span> error<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  Sentry<span class="token punctuation">.</span><span class="token function">captureException</span><span class="token punctuation">(</span>error<span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">extra</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">url</span><span class="token operator">:</span> event<span class="token punctuation">.</span>url<span class="token punctuation">.</span>href <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 可返回自定义错误信息（但不会改变 UI）</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">message</span><span class="token operator">:</span> <span class="token string">&#39;An unexpected error occurred&#39;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：</p><ul><li>不会阻止错误发生，仅用于<strong>日志记录</strong></li><li>实际错误界面由 <code>+error.svelte</code> 控制</li></ul></blockquote></li></ol><h2 id="_4-3-动态路由参数验证" tabindex="-1"><a class="header-anchor" href="#_4-3-动态路由参数验证"><span>4.3 动态路由参数验证</span></a></h2><p>在 SvelteKit 中，<strong><code>/src/params</code></strong> 是一个<strong>可选的特殊目录</strong>，用于<strong>自定义动态路由参数（<code>[param]</code>）的解析和验证逻辑</strong>。</p><p>它的核心作用是：</p><blockquote><p><strong>当你在路由中使用 <code>[id]</code>、<code>[slug]</code> 等动态参数时，可以通过 <code>src/params/xxx.js</code> 定义该参数的校验规则和类型转换逻辑。</strong></p></blockquote><h3 id="_4-3-1-为什么需要-src-params" tabindex="-1"><a class="header-anchor" href="#_4-3-1-为什么需要-src-params"><span>4.3.1 为什么需要 <code>src/params</code>？</span></a></h3><p>默认情况下，SvelteKit 会把 URL 中的动态参数（如 <code>/blog/[slug]</code>）作为 <strong>字符串</strong> 传递给你的页面：</p><div class="language-svelte line-numbers-mode" data-highlighter="prismjs" data-ext="svelte"><pre><code class="language-svelte"><span class="line">&lt;!-- 访问 /blog/hello-world --&gt;</span>
<span class="line">&lt;script&gt;</span>
<span class="line">  export let data;</span>
<span class="line">  // data.slug === &quot;hello-world&quot; （字符串）</span>
<span class="line">&lt;/script&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>但很多时候你需要：</p><ul><li>验证参数格式（如 <code>id</code> 必须是数字）</li><li>自动转换类型（如字符串 <code>&quot;123&quot;</code> → 数字 <code>123</code>）</li><li>拒绝不合法参数（返回 404）</li></ul><p>这时候 <code>src/params</code> 就派上用场了！</p><h3 id="_4-3-2-基本用法" tabindex="-1"><a class="header-anchor" href="#_4-3-2-基本用法"><span>4.3.2 基本用法</span></a></h3><ul><li><p>步骤 1：创建参数解析器文件</p><p>文件名必须与路由中的参数名一致：</p><div class="language-plain line-numbers-mode" data-highlighter="prismjs" data-ext="plain"><pre><code class="language-plain"><span class="line">src/</span>
<span class="line">├── params/</span>
<span class="line">│   ├── id.js        // 处理 [id]</span>
<span class="line">│   ├── slug.js      // 处理 [slug]</span>
<span class="line">│   └── date.js      // 处理 [date]</span>
<span class="line">└── routes/</span>
<span class="line">    └── blog/</span>
<span class="line">        └── [slug]/+page.svelte</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>步骤 2：导出 <code>match</code> 和/或 <code>parse</code> 函数</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/params/id.js</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * 校验参数是否合法（正则或函数）</span>
<span class="line"> * <span class="token keyword">@param</span> <span class="token class-name"><span class="token punctuation">{</span>string<span class="token punctuation">}</span></span> <span class="token parameter">param</span> - URL 中的原始字符串</span>
<span class="line"> * <span class="token keyword">@returns</span> <span class="token class-name"><span class="token punctuation">{</span>boolean<span class="token punctuation">}</span></span></span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">match</span><span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^\\d+$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 只允许纯数字</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * 将字符串转换为目标类型（可选）</span>
<span class="line"> * <span class="token keyword">@param</span> <span class="token class-name"><span class="token punctuation">{</span>string<span class="token punctuation">}</span></span> <span class="token parameter">param</span></span>
<span class="line"> * <span class="token keyword">@returns</span> <span class="token class-name"><span class="token punctuation">{</span>number<span class="token punctuation">}</span></span></span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">parse</span><span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token function">parseInt</span><span class="token punctuation">(</span>param<span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>如果只导出 <code>match</code>，参数仍为字符串；<br> 如果同时导出 <code>parse</code>，参数会被自动转换。</p></blockquote></li></ul><h3 id="_4-3-3-完整示例" tabindex="-1"><a class="header-anchor" href="#_4-3-3-完整示例"><span>4.3.3 完整示例</span></a></h3><ul><li><p>示例 1：数字 ID 参数</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/params/id.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">match</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^\\d+$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">parse</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">Number</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>路由：</p><div class="language-svelte line-numbers-mode" data-highlighter="prismjs" data-ext="svelte"><pre><code class="language-svelte"><span class="line">&lt;!-- src/routes/users/[id]/+page.svelte --&gt;</span>
<span class="line">&lt;script&gt;</span>
<span class="line">  /** @type {import(&#39;./$types&#39;).PageData} */</span>
<span class="line">  export let data;</span>
<span class="line">  // data.id 是 number 类型！</span>
<span class="line">&lt;/script&gt;</span>
<span class="line"></span>
<span class="line">&lt;h1&gt;User ID: {data.id}&lt;/h1&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>服务端加载：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/routes/users/[id]/+page.server.js</span></span>
<span class="line"><span class="token keyword">import</span> type <span class="token punctuation">{</span> PageServerLoad <span class="token punctuation">}</span> <span class="token keyword">from</span> <span class="token string">&#39;./$types&#39;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> load <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> params <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">//  params.id 已经是 number！</span></span>
<span class="line">  <span class="token keyword">const</span> user <span class="token operator">=</span> <span class="token keyword">await</span> db<span class="token punctuation">.</span><span class="token function">getUserById</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> user <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span> satisfies PageServerLoad<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>如果访问 <code>/users/abc</code>，SvelteKit 会自动返回 <strong>404 Not Found</strong>（因为 <code>match</code> 返回 false）。</p></blockquote></li><li><p>示例 2：日期参数（YYYY-MM-DD）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/params/date.js</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token constant">DATE_REGEX</span> <span class="token operator">=</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^\\d{4}-\\d{2}-\\d{2}$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">match</span><span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token constant">DATE_REGEX</span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> date <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Date</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token operator">!</span><span class="token function">isNaN</span><span class="token punctuation">(</span>date<span class="token punctuation">.</span><span class="token function">getTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 验证是否为有效日期</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">parse</span><span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token class-name">Date</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 转为 Date 对象</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// routes/events/[date]/+page.server.js</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">load</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter"><span class="token punctuation">{</span> params <span class="token punctuation">}</span></span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// params.date 是 Date 对象！</span></span>
<span class="line">  <span class="token keyword">const</span> events <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">getEventsOnDate</span><span class="token punctuation">(</span>params<span class="token punctuation">.</span>date<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span> events <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>示例 3：仅校验，不转换（保留字符串）</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// src/params/slug.js</span></span>
<span class="line"><span class="token comment">// 只允许小写字母、数字、连字符</span></span>
<span class="line"><span class="token keyword">export</span> <span class="token keyword">const</span> <span class="token function-variable function">match</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token parameter">param</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">^[a-z0-9-]+$</span><span class="token regex-delimiter">/</span></span><span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>param<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 不导出 parse → 保持字符串</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul>`,40)])])}const i=n(t,[["render",l]]),r=JSON.parse('{"path":"/framework/svelte/svelteKit/04.html","title":"四、其他相关","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772001712000,"contributors":[{"name":"zhao-farmer","username":"zhao-farmer","email":"857899180@qq.com","commits":2,"url":"https://github.com/zhao-farmer"}],"changelog":[{"hash":"db6d183fe4bedd50d548f87979aa938388a2e519","time":1772001712000,"email":"857899180@qq.com","author":"zhao-farmer","message":"新提交"},{"hash":"6456dcf1fd45f82d71ce5dfe3954468d5bf78145","time":1771996569000,"email":"857899180@qq.com","author":"zhao-farmer","message":"新提交"}]},"filePathRelative":"framework/svelte/svelteKit/04.md"}');export{i as comp,r as data};
